INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:147','mayalex_normativos','01_PENAL','Deber de colaborar. Las autoridades y funcionarios públicos colaborarán con los jueces, el Ministerio Público y la Policía Nacional, en el cumplimiento de sus cometidos, para lo cual tramitarán sin dilación, los requerimientos que les formulen.','147','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":151,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"1cccc1a624c90d216cc5b05b848191bf2b8f5c16764c24160a3ec0d43f16c32a","article_sha256":"80ab6b6f72ac13b3b418638ec31e612e542aa979deaf6981a6581b6767eb6288","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a147","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','147','80ab6b6f72ac13b3b418638ec31e612e542aa979deaf6981a6581b6767eb6288','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:148','mayalex_normativos','01_PENAL','Incumplimiento, retardo y rechazo de un requerimiento. Cuando el requerimiento sea cumplido sólo parcialmente o en forma indebida, o se demore o rechace sin causa justificada, el requirente podrá solicitar a la Corte Suprema de Justicia. Al Fiscal General de la República o al Secretario de Estado en el Despacho de Seguridad, según proceda, que ordene o gestione el inmediato y correcto cumplimiento de la comunicación. Tales autoridades, además, aplicarán al respectivo funcionario, las medidas disciplinarias que correspondan y, en el caso de rechazo sin causa justificada, previsto en este artículo, darán cuenta al Ministerio Público, para los efectos de lo establecido en el Código Penal.','148','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":152,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"c363847da80f10c6971fc16b57a42056b02927a38eea958e4b901d82c918ca8e","article_sha256":"f6c6c9c0c4310b29b94e5a43b7f3e405b320c0dcaa500916e6e7a1488161e1d9","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a148","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','148','f6c6c9c0c4310b29b94e5a43b7f3e405b320c0dcaa500916e6e7a1488161e1d9','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:149','mayalex_normativos','01_PENAL','Requerimientos a tribunales extranjeros. Los requerimientos dirigidos a tribunales o autoridades extranjeras, o los recibidos de ellos, serán tramitados por la vía diplomática. En casos excepcionales y de suma importancia, el juez o el miembro de un Tribunal de Sentencia que se designe para el efecto, podrá realizar diligencias en otro Estado, previa autorización de éste.

Lo dispuesto en el artículo 148 que antecede, será aplicable en lo procedente a lo dispuesto en esta norma.','149','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":153,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"a8a84ff2bf26ac5c2285b5f6927c58b751599871bf827d59cb1d395634856f6f","article_sha256":"bc025abbfbd7852587c5ad3349fafeda6ff6dbe912727f8a81007b8f040542ce","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a149","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','149','bc025abbfbd7852587c5ad3349fafeda6ff6dbe912727f8a81007b8f040542ce','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:150','mayalex_normativos','01_PENAL','La extradición de imputados. La extradición de imputados o condenados, se regirá por lo establecido en los tratados internacionales de los que Honduras forma parte y por las leyes del país.','150','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":154,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"74ffce118ca32396aaaa2e4bf7f89ec8062d5b10026de118a9d457491dde8683","article_sha256":"8cf517b635c2ec11c363395f3aa98f7a85c1bae9b3e1ac0bf53bd180db689cb3","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a150","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','150','8cf517b635c2ec11c363395f3aa98f7a85c1bae9b3e1ac0bf53bd180db689cb3','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:151','mayalex_normativos','01_PENAL','La notificación de las resoluciones. Las resoluciones de los órganos jurisdiccionales se notificarán, de oficio personalmente, a todos los intervinientes a más tardar el día siguiente al de su fecha. De no ser esto posible, las notificaciones se harán por medio de cédulas o de edictos.

Las resoluciones se notificarán, igualmente, a quienes podrían resultar perjudicados por las mismas, aunque no sean parte del proceso, así como, a quienes se refieran si así se manda y ello es posible.

Las notificaciones personales las hará el receptor del órgano jurisdiccional y, en su defecto, el secretario. Para el cumplimiento de tal cometido, dichos funcionarios podrán solicitar el auxilio de las autoridades de policía, si lo estiman necesario.

La notificación se hará leyendo íntegramente la resolución al notificado, entregándole copia textual de la misma. De lo anterior se dejará constancia en el formulario, así como, del asunto de que se trate y del lugar, día y hora de la diligencia, la cual deberá ser firmada por el notificante y por el notificado, si éste puede y quiere hacerlo. En caso de negativa, se dejará constancia de este hecho en el respectivo formulario.','151','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":155,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"3c9c91b673e53623fa6dfb6350f5064e8af2b991dcda54f339b6d8e2b2932691","article_sha256":"480baa077057bacfeef8366c0ea6e60c8c135e288d78ca23c4e1e1a27713b58c","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a151","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','151','480baa077057bacfeef8366c0ea6e60c8c135e288d78ca23c4e1e1a27713b58c','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:152','mayalex_normativos','01_PENAL','Lugar en que deben hacerse las notificaciones. Las notificaciones a los apoderados legales de las partes se harán en el asiento del órgano jurisdiccional o en el lugar que hayan señalado para tal efecto. En este último caso, la notificación se hará por medio de cédula, que será entregada a cualquier persona mayor de catorce (14) años que se encuentre en el indicado lugar. Si nadie se encuentra en el mismo o quien se encuentre se niega a recibir la cédula, ésta se fijará en la puerta del acceso principal del referido lugar. De estas diligencias se dejará constancia en los correspondientes autos, las que serán firmadas por el notificante y por la persona que haya recibido la cédula, en su caso.','152','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":156,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"9858f6f39e889c24386e098754028d792cdf08aa9eb00b6a23a72bd08b6e3424","article_sha256":"2c48f4717d85cc16d688914fa4ed17659cf3534b05581a664c9300361e4f0364","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a152","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','152','2c48f4717d85cc16d688914fa4ed17659cf3534b05581a664c9300361e4f0364','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:153','mayalex_normativos','01_PENAL','Contenido de la cédula de notificación. La cédula de notificación a que se refiere el artículo anterior contendrá:

1) El nombre del órgano jurisdiccional que ordena la notificación;

2) El nombre y apellidos de la persona natural o representante legal de la persona jurídica;

3) El objeto del proceso y los nombres y apellidos de las partes;

4) Copia literal de la parte resolutiva de la decisión judicial que se notifica;

5) El lugar, fecha y hora de la notificación; y,

6) La firma del notificante con indicación de su cargo.','153','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":157,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"6e10873dea94bd4b9471154a3dc4bc6cd869f4a5f54bb7aeed02df8f8980691d","article_sha256":"30e61f0f972c2c42b72681bd9e40a9f849608bd3769d8575b1c06d4eadf6f2a4","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a153","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','153','30e61f0f972c2c42b72681bd9e40a9f849608bd3769d8575b1c06d4eadf6f2a4','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:154','mayalex_normativos','01_PENAL','Citaciones y emplazamientos. Las partes en un proceso, así como, los testigos y peritos, serán citados y emplazados personalmente por el receptor del órgano jurisdiccional y en su defecto, por el empleado a quien se le asigne esa función, la cual deberá desempeñar previa promesa de ley, adquiriendo uno y otro el carácter de ministro de fe público. Tales diligencias, excepto la notificación personal, se practicarán por medio de cédulas, a las que se acompañarán la copia de la acusación o querella, en su caso. Inmediatamente después de efectuadas, pondrá razón de las mismas en los autos el funcionario judicial competente.

Cuando la citación o emplazamiento haya de hacerse por medio de comunicación, se acompañará la cédula correspondiente.','154','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":158,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"90e1e10d1539888af2f0b9030d6f2758808a3230c0d4be4be004373b42028750","article_sha256":"8419510a55395572e17e91e8126f93a13d349cb88b93fe915d18260bb63c3428","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a154","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','154','8419510a55395572e17e91e8126f93a13d349cb88b93fe915d18260bb63c3428','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:155','mayalex_normativos','01_PENAL','Contenido de la cédula de citación. La cédula de citación contendrá:

1) La denominación y lugar del órgano jurisdiccional que haya dictado la providencia, la fecha de ésta y el asunto en el que ha recaído;

2) El nombre y apellidos de la persona natural o representante legal de la persona jurídica a quien debe hacerse la citación;

3) El objeto de la citación y la parte que la haya solicitado;

4) El lugar, día y hora en que debe comparecer la persona citada; y,

5) La prevención de que, si no comparece, se le deducirán las responsabilidades a que haya lugar en derecho.

A los testigos y peritos se les hará la prevención de que, si no comparecen sin justa causa, serán procesados por el delito de desobediencia. Se estará, además, a lo dispuesto por los artículos 232 y 240 del presente Código.','155','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":159,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"025b0efa33c6f5e9bdda1e4144033af86609500e84cbdcfe1dd1b95cc727040a","article_sha256":"82a445518eea0314d0a812b6bdf694ba6edf54cda55aed8b8212770b558339a3","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a155","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','155','82a445518eea0314d0a812b6bdf694ba6edf54cda55aed8b8212770b558339a3','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:156','mayalex_normativos','01_PENAL','Los requerimientos. Los requerimientos se harán mediante notificación de la providencia en que se ordenen, dejando constancia en autos.','156','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":160,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"d4bbca9f523d6411dd12e322effe5b677af560702da468945a5c86f21f7c9fe2","article_sha256":"3ed5629dd72160aca0065cddb17ccf16b6664b8cc130019fba84ab5ccb632dd4","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a156","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','156','3ed5629dd72160aca0065cddb17ccf16b6664b8cc130019fba84ab5ccb632dd4','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:157','mayalex_normativos','01_PENAL','Notificación y citación por edictos. Cuando se ignore el lugar en que se encuentra la persona que deba ser notificada, citada, emplazada o requerida, el órgano jurisdiccional ordenará la publicación de edictos por tres (3) días, en dos de los radio periódicos de mayor audiencia en el país. Los edictos también podrán publicarse en dos de los diarios escritos de mayor circulación en la República o por medio de la televisión. En todos los casos, se dejará constancia en autos, de la publicación.

El edicto contendrá:

1) La denominación y lugar del órgano jurisdiccional que haya dictado la providencia, la fecha de ésta y el asunto en que ha recaído;

2) El nombre y apellidos de la persona natural o representante legal de la persona jurídica; y,

3) La orden de personarse al órgano jurisdiccional para ser notificado, citado, emplazado o requerido.','157','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":161,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"bf05d67bb754098be02e2529754aa457a58d2b636240a33be144917197d44b98","article_sha256":"2641df1bd981de7cf67c6d11d0a9a3b1b85db63105de0a942f615fb54059f9c2","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a157","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','157','2641df1bd981de7cf67c6d11d0a9a3b1b85db63105de0a942f615fb54059f9c2','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:158','mayalex_normativos','01_PENAL','Prohibición de respuesta. En las notificaciones, citaciones, emplazamientos y requerimientos, no se consignará respuesta alguna de las personas a quienes se les haga, pero estos tendrán el derecho de recurrir en el término establecido para impugnar la resolución en el momento de la notificación.','158','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":162,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"14e7ec92dad8dec528d639923a9a3ffc4dd8a18f70687bc29655905bcd69191a","article_sha256":"d72b3dcd0dc23e344c928cf6de7e08c2ca3116d237e8f77eee78ea8b04c5d25b","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a158","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','158','d72b3dcd0dc23e344c928cf6de7e08c2ca3116d237e8f77eee78ea8b04c5d25b','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:159','mayalex_normativos','01_PENAL','Sanción de la contravención a lo dispuesto en este capítulo. Serán nulas las notificaciones, citaciones, emplazamientos y requerimientos que no se practiquen con arreglo a lo dispuesto en este capítulo.

No obstante, si la persona indebidamente notificada, citada, emplazada o requerida no reclama en juicio la nulidad del respectivo acto, la diligencia surtirá todos sus efectos como si se hubiera hecho con arreglo a las disposiciones de la ley.

Lo dispuesto en el párrafo anterior, se aplicará también cuando la correspondiente diligencia no se haya realizado en manera alguna, siempre que el notificado, citado, emplazado o requerido se hubiera dado por enterado. No por esto, quedará relevado el notificante de la sanción disciplinaria que merezca.','159','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":163,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"86f049066de099f82fc57bb9c304382cc6f1849f03ad4b0cff3a9be9574e7025","article_sha256":"5b1342b7ffaf55993c3d157cf507cc1165d5c2faee95f869bf33d336f0f25924","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a159","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','159','5b1342b7ffaf55993c3d157cf507cc1165d5c2faee95f869bf33d336f0f25924','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:160','mayalex_normativos','01_PENAL','Los actos procesales y los plazos. Los actos procesales serán cumplidos dentro de los plazos establecidos por la ley o por los tribunales de justicia.

Los plazos legales y judiciales se regirán por lo dispuesto en el Título Preliminar del Código Civil.','160','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":164,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"d823548669f5a1c220cf700652d2e7606cd76d423403de599cc8e68d64596a78","article_sha256":"35ca69229acb3bf33feb62bc7cba1e4c54425776ac2516c39c3e72b99ed9b19a","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a160","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','160','35ca69229acb3bf33feb62bc7cba1e4c54425776ac2516c39c3e72b99ed9b19a','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:161','mayalex_normativos','01_PENAL','Plazos y términos judiciales. Cuando la ley permita a los órganos jurisdiccionales fijar términos o plazos, éstos se establecerán tomando en cuenta la naturaleza del procedimiento, la importancia de la actividad que deba cumplirse y los derechos de las partes.','161','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":165,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"2db20fb5b65c748578a6e7ea4d41ce6dc6a4e47b5a45f9136f74fbb30efda0eb","article_sha256":"75efe74143e201379ea7cc26ca16dd89c421436357ea5bdc014a5f2ec7185222","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a161","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','161','75efe74143e201379ea7cc26ca16dd89c421436357ea5bdc014a5f2ec7185222','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:162','mayalex_normativos','01_PENAL','Reposición del plazo. Las partes podrán solicitar la reposición total o parcial de un plazo, cuando por defecto de la notificación o por fuerza mayor o caso fortuito, no hayan podido observarlo.

La solicitud deberá presentarse por escrito ante el correspondiente órgano jurisdiccional competente, dentro de las cuarenta y ocho horas (48) siguientes al momento en que cesó la fuerza mayor o el caso fortuito o de haberse conocido la providencia en que se señaló el plazo.

Dicha solicitud indicará, en forma breve, el motivo que haya imposibilitado la observancia del plazo y propondrá las pruebas correspondientes.','162','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":166,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"8ceab43055f988b3b7f9c84ae82ba8bd8aa269c844a4febfd390ca25d2b529a9","article_sha256":"059f45c03cc687b2c522bd5b3433c5f924ef5e7a3eda029f65d12c9379ee6738","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a162","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','162','059f45c03cc687b2c522bd5b3433c5f924ef5e7a3eda029f65d12c9379ee6738','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:163','mayalex_normativos','01_PENAL','Atención judicial permanente y continua. Las autoridades judiciales dispondrán lo necesario para que los funcionarios de cada órgano jurisdiccional, reciban las solicitudes y escritos de las partes en forma continuada y permanente, aún fuera de las jornadas ordinarias de trabajo.

A tal efecto, la Corte Suprema de Justicia organizará en las distintas circunscripciones judiciales, un sistema de turnos y guardias u oficinas de atención permanente al público.','163','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":167,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"dfef97694cd5262bc528f9f0bec613e4d4204676793696d27430d9aa83a569f7","article_sha256":"e24db6f2124005cc5c34803f51670fa0c6938d1884be552399561544632313e3","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a163","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','163','e24db6f2124005cc5c34803f51670fa0c6938d1884be552399561544632313e3','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:164','mayalex_normativos','01_PENAL','Renuncia o abreviación de términos o plazo. Las partes a cuyo favor se ha señalado un plazo o término legal o judicial sean éstas individuales o comunes, podrán renunciarlo o abreviarlo mediante expresa manifestación de voluntad ante la autoridad competente.

Cuando el plazo sea común, se reputará que existe renuncia o abreviación, mediante la expresa manifestación de voluntad de las partes.','164','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":168,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"3aa78f7c31e23931829e2a9c8d86f1936a5e1a6d5dc2ded789a94f9f2f1ec9b8","article_sha256":"fd12b2ce5b95c73e126e479efd70f75f0c04c8ff43a3bb292f44c94184031828","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a164","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','164','fd12b2ce5b95c73e126e479efd70f75f0c04c8ff43a3bb292f44c94184031828','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:165','mayalex_normativos','01_PENAL','Principio de excepcionalidad de la nulidad. La inobservancia de las normas contenidas en este Código, solo producirá la nulidad de los actos procedimentales, cuando así se establezca expresamente, sin perjuicio de la responsabilidad penal, civil o disciplinaria en que hayan podido incurrir los infractores.','165','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":169,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"fb93475b00b733a16f0b8a8442524340470ad699a92f4de966e25655e6a5e8a0","article_sha256":"ee5c9d38bea3a8c24513f7ae03e7ff579e5b87ba56e7f4e57c65e4b04e3742a5","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a165","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','165','ee5c9d38bea3a8c24513f7ae03e7ff579e5b87ba56e7f4e57c65e4b04e3742a5','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:166','mayalex_normativos','01_PENAL','Casos de nulidad de los actos procedimentales. Serán nulos los actos procedimentales realizados:

1) Con inobservancia de las disposiciones concernientes al nombramiento, capacidad, jurisdicción o competencia de los órganos jurisdiccionales o de sus integrantes;

2) Con inobservancia de las disposiciones concernientes a la iniciativa de los fiscales y de los acusadores privados, y a su participación en los actos en que su intervención sea necesaria;

3) Con inobservancia de las disposiciones concernientes a la intervención y participación del imputado en el procedimiento, y las relativas a su representación y defensa;

4) Por error sobre sus presupuestos de hecho o bajo violencia física o por efecto de intimidación racional y fundada de un mal inminente y grave, sin perjuicio de las responsabilidades en que podría incurrir la persona causante de la violencia o de la intimidación;

5) Con infracción de las normas esenciales de procedimiento establecidas por este Código, que impida que el acto logre la finalidad que persigue la norma correspondiente;

6) Con infracción de los principios de igualdad entre las partes, de audiencia, contradicción, asistencia y defensa, siempre que hayan producido una efectiva indefensión; y,

7) Con violación de los derechos y libertades fundamentales de la persona, consagradas por la Constitución de la República, los Tratados Internacionales de los cuales Honduras forma parte y demás leyes.','166','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":170,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"b5bdb13b41049bb13e138f5a98b4b811c771686a39ab7e236f03a28a89299f42","article_sha256":"4cc1d9bd489ffc8c1737efe3e8d13792d7ec8c300163a9091ef5809d6e790053","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a166","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','166','4cc1d9bd489ffc8c1737efe3e8d13792d7ec8c300163a9091ef5809d6e790053','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:167','mayalex_normativos','01_PENAL','Personas que pueden solicitar la nulidad y las oportunidades procesales. Los actos en los cuales concurra causa de nulidad, serán anulables por reclamación de la parte perjudicada, interpuesta en las oportunidades procesales siguientes:

1) La nulidad de los actos realizados durante la etapa preparatoria del proceso, en la primera audiencia;

2) La de los realizados durante la audiencia preliminar, antes del auto de apertura de juicio oral;

3) La de los realizados en el auto de apertura del juicio o en el momento de la notificación de éste, en fase de preparación del juicio;

4) Las causas de nulidad por hechos sobrevenidos con posterioridad, o por hechos precedentes que no hubieran sido conocidos con anterioridad, en la audiencia anterior al debate, de conformidad con lo previsto por el artículo 316 de este Código; y,

5) Las producidas en el curso del debate o durante la tramitación de un recurso, antes de que (1) uno u otro concluyan.

La pretensión anulatoria deberá ser motivada y será resuelta en audiencia dentro de los tres (3) días hábiles siguientes a la fecha de su interposición.

Las que se presenten durante una audiencia, se formularán verbalmente y serán resueltas de inmediato.

No podrá pretender la anulación la parte que dio lugar a la causa de nulidad. El órgano jurisdiccional rechazará la pretensión anulatoria, cuando mediante ella se intente tan solo dilatar indebidamente el procedimiento o corregir cualquier deficiencia imputable al reclamante, cuando éste haya dejado precluir la oportunidad de subsanarla.','167','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":171,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"e8e0230c1cb18c419d3dc97d64c58452330b2f3d7af5b6c752ca160e99d5d885","article_sha256":"6c40ad6beacade00a7311bb11db89873d04c0ec7f43fddca6f464b94bd8d4d84","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a167","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','167','6c40ad6beacade00a7311bb11db89873d04c0ec7f43fddca6f464b94bd8d4d84','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:168','mayalex_normativos','01_PENAL','Declaración de nulidad de oficio. En los casos expresamente establecidos en este Código, el órgano jurisdiccional podrá apreciar y declarar la nulidad

por propia iniciativa, previa audiencia de las partes, con el alcance previsto en el artículo 169, en sus respectivos casos.','168','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":172,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"f613e72ae0a5bcc9b4e07be664ee7a4c1cd8f67faf2d02d8d2f3a2307628c1b8","article_sha256":"3fa7e56e8549e0cd32e2b35a3c78143dcd64432fb9478b4581fce7d6adfec92a","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a168","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','168','3fa7e56e8549e0cd32e2b35a3c78143dcd64432fb9478b4581fce7d6adfec92a','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:169','mayalex_normativos','01_PENAL','Alcance de la nulidad. Conservación de eficacia de los actos procesales. Declarada la nulidad, carecerán de valor y efecto alguno no solo el acto viciado, sino también todos los que se hayan realizado con posterioridad, siempre que dependan directamente de aquél y sean determinados expresamente por el órgano jurisdiccional.

Cuando se declare la nulidad parcial de un acto, sus efectos no se extenderán a las partes no afectadas por aquélla.

La nulidad de un acto no lleva consigo la de las actuaciones sucesivas que fueren independientes de aquél, ni la de aquéllas cuyo contenido habría permanecido, invariable, incluso de no haberse cometido la infracción que dio lugar a la nulidad.','169','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":173,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"c7afa3829afb6fbb217ad320d32bb57152de7f9586ef621578d268ab5bc4be01","article_sha256":"c066c4f562f8bfd14e7c6993eac8dd1322c72b10c7f9128ed8e787d58df81190","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a169","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','169','c066c4f562f8bfd14e7c6993eac8dd1322c72b10c7f9128ed8e787d58df81190','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:170','mayalex_normativos','01_PENAL','Subsanación de actos viciados. Salvo que se disponga expresamente lo contrario, los actos viciados se tendrán por subsanados cuando:

1) Ninguna de las partes haya reclamado oportunamente la declaración de su nulidad, sin perjuicio del poder de iniciativa judicial en los casos expresamente determinados por este Código;

2) Las partes hayan aceptado, expresa o tácitamente, los efectos del acto viciado de nulidad;

3) No obstante el vicio, se haya alcanzado la finalidad perseguida mediante el acto viciado; y,

4) El órgano jurisdiccional, de oficio o a petición de parte, haya podido eliminar la causa de nulidad.','170','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":174,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"0b624eb6aac3388d8f009c2e5d3f7df8b95fec77abd362d948fe60006b7ea84c","article_sha256":"841e6f7c1a6b858f4cb0a773abc1168d6196323c9afb4aa44fe650de6597bffb","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a170","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','170','841e6f7c1a6b858f4cb0a773abc1168d6196323c9afb4aa44fe650de6597bffb','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:171','mayalex_normativos','01_PENAL','Saneamiento. Los defectos deberán ser saneados de oficio o a instancia del interesado siempre que sea posible, renovando el acto, rectificando el error o cumpliendo con el acto omitido.

Salvo los casos expresamente previstos por este Código, no puede retrotraerse el proceso a períodos ya precluidos, bajo pretexto de renovación del acto, de rectificación del error o cumplimiento del acto omitido.','171','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":175,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"154e7ff4ca8fdf109d1836b79754518d9c852556b0a20790430f1803aa6d2bff","article_sha256":"503efba1c084fddc97d6bedca0ea748a57922d0e651809362e6049a59abbf8e1","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a171","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','171','503efba1c084fddc97d6bedca0ea748a57922d0e651809362e6049a59abbf8e1','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:172','mayalex_normativos','01_PENAL','Medidas cautelares personales: presupuestos y finalidad. Las medidas cautelares tienen como finalidad, asegurar la eficacia del procedimiento, garantizando la presencia del imputado y la regular obtención de las fuentes de prueba.

Para que pueda adoptarse una medida cautelar limitativa de la libertad personal, será siempre preciso:

1) Que existan suficientes indicios para sostener razonablemente que el imputado es autor o partícipe de un hecho tipificado como delito;

2) Que la persona imputada se haya fugado o exista motivo fundado para temer que podría darse a la fuga en caso de permanecer en libertad; y,

3) Que existan fundados motivos para temer que, puesta en libertad, el imputado tratará de destruir o manipular las fuentes de prueba.','172','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":176,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"b7a765bcad6cf17143ae2f051e98593948e20d8ffdcfaa63ef6145c56f960c8f","article_sha256":"2f4d9cc8dd4799a968689d1cbc9c2b3dd13d9a1fea256bb0b8a275a504b6fc47","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a172","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','172','2f4d9cc8dd4799a968689d1cbc9c2b3dd13d9a1fea256bb0b8a275a504b6fc47','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:173','mayalex_normativos','01_PENAL','Medidas cautelares aplicables. El órgano jurisdiccional, concurriendo los presupuestos legitimadores, podrá adoptar, por auto motivado, una o más de las medidas cautelares siguientes:

1) Aprehensión o captura;

2) Detención preventiva;

3) Prisión preventiva;

4) Arresto en su propio domicilio o en el de otra persona que lo consienta, bajo vigilancia o sin ella;

5) Someter al imputado al cuidado o vigilancia de una persona o institución determinada que informe periódicamente al juez;

6) Obligar al imputado a presentarse periódicamente ante un determinado juez o autoridad que éste designe;

7) Prohibirle al imputado salir del país, del lugar de su residencia o del ámbito territorial que el órgano jurisdiccional determine;

8) Prohibirle al imputado concurrir a determinadas reuniones o a determinados lugares;

9) Prohibirle al imputado comunicarse con personas determinadas, siempre que con ello no se afecte el derecho de defensa;

10) La constitución a favor del Estado por el propio imputado o por otra persona, de cualquiera de las garantías siguientes: Depósito de dinero o valores, hipoteca, prenda o fianza personal;

11) El internamiento provisional en un establecimiento psiquiátrico, previo dictamen; y,

12) Suspensión en el ejercicio del cargo, cuando se le atribuya un delito contra la administración pública.

Para los mismos fines previstos en este Artículo, y para los efectos de la investigación, el Ministerio Público en caso de urgente necesidad que impida recabar la autorización judicial, podrá adoptar una o más de las medidas cautelares previstas en los numerales 1), 2), 7), 9) y 11) de este artículo. Inmediatamente lo pondrá en conocimiento del órgano jurisdiccional, exponiendo las razones que impidieron obtener aquella autorización. El órgano jurisdiccional, oída la persona imputada y su defensor, convalidará o dejará sin efecto lo dispuesto por el Ministerio Público.

Para controlar el cumplimiento de las medidas establecidas en los numerales 4), 5), 6)
7) y 9), debe ser aplicable lo relativo al sistema de vigilancia electrónica personal, al tenor de las circunstancias y regulaciones apuntadas en los artículos siguientes.','173','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":177,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"034ed7a04f52b21d02a8a7087e37dd03563d6e33294c6decb586abe5d10ef05b","article_sha256":"6278da7e62edd08bede02c421c3859aba311fb2f3f9dab97e919b74a39875a9f","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a173","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','173','6278da7e62edd08bede02c421c3859aba311fb2f3f9dab97e919b74a39875a9f','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:173-A','mayalex_normativos','01_PENAL','El juez determinará la modalidad a aplicar para cada persona. Una será la vigilancia electrónica con restricción al perímetro del domicilio y otra es la que permita el tránsito restringido.

En los casos en que el juez considere procedente aplicar la vigilancia electrónica personal, el acta que se levante en la respectiva audiencia, debe contener además lo siguiente:

1.- El domicilio o el lugar donde cumplirá la medida o será el punto de referencia para su radio de acción y desplazamiento geográfico;

2.- El enunciado de los derechos, obligaciones, restricciones y responsabilidades a las que tendrá que sujetarse el procesado o condenado;

3.- El compromiso de no cambiar su domicilio, sin previa autorización judicial;

4.- El compromiso de concurrir ante las autoridades policiales, fiscales o judiciales, las veces que sea requerido, a fin de verificar que cumpla con las condiciones de la medida;

5.- El compromiso de no manipular o dañar el dispositivo electrónico, por si mismo, a través de terceros o mediante el uso de sistemas electrónicos o informáticos que impidan o dificulten su normal funcionamiento; y,

6.- Todas aquellas otras precisiones que considere pertinente el juez.','173-A','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":178,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"d0bea9afd02e55a385be473cad27a806d8d230407e5f5174eb21789e9c2460f4","article_sha256":"8a5f71ff0b8cf5a20a856000602a6efe9f04de816ba963af80d39761e06ec5b5","constancias":[{"nota":18,"tipo":"ADICION","texto":"Artículo 173-A. Adicionado por Decreto No. 98-2017 de fecha 27 de septiembre de 2017 y publicado en el Diario Oficial La Gaceta No.34,473 de fecha 24 de octubre de 2017.","decretos":["98-2017"]}],"correcciones_saneamiento":["LLAMADA_EN_ENCABEZADO","REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a173_a","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','173-A','8a5f71ff0b8cf5a20a856000602a6efe9f04de816ba963af80d39761e06ec5b5','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:173-B','mayalex_normativos','01_PENAL','Si el imputado o condenado incumpliese alguna de las obligaciones o restricciones impuestas al concederle la medida de vigilancia electrónica personal, el juez de oficio o a petición del fiscal, ordenará su inmediato internamiento en un establecimiento penitenciario.

El juez no podrá aplicar esta medida en casos de reincidencia o habitualidad en la comisión de delitos.

Tampoco podrá disponer el uso de estos mecanismos de control en personas que tengan marcapasos u otros dispositivos médicos similares y que se pudieren ver afectados con la herramienta de monitoreo.','173-B','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":179,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"3978b71cfe9d4c1a35cfdbccf7c7040475005c81de0e1877ddc9cbdfa34030fd","article_sha256":"e90913500006ff71d1182885c8646ed31cf4362cc5b2a41d3a66bbd934e4e736","constancias":[{"nota":19,"tipo":"ADICION","texto":"Artículo 173-B. Adicionado por Decreto No. 98-2017 de fecha 27 de septiembre de 2017 y publicado en el Diario Oficial La Gaceta No.34,473 de fecha 24 de octubre de 2017.","decretos":["98-2017"]}],"correcciones_saneamiento":["LLAMADA_EN_ENCABEZADO","REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a173_b","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','173-B','e90913500006ff71d1182885c8646ed31cf4362cc5b2a41d3a66bbd934e4e736','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:174','mayalex_normativos','01_PENAL','Imposición, revocación y reforma de las resoluciones sobre medidas cautelares. Las medidas cautelares personales habrán de ser dispuestas por el órgano jurisdiccional competente, por auto motivado, en el que se justificará la concurrencia de los presupuestos legitimadores, invocando los indicios que resulten de las investigaciones realizadas.

El órgano jurisdiccional, al seleccionar la medida aplicable, deberá tener en cuenta su idoneidad y proporcionalidad en relación con los fines que se pretende conseguir, teniendo en cuenta la gravedad del hecho y de la pena que, en caso de condena, podría ser impuesta y las circunstancias personales del imputado.

Las medidas adoptadas no durarán más tiempo que el imprescindible para asegurar los fines por los que se aplicaron y, en ningún caso, se prolongarán más allá del máximo permitido por el artículo 181 de este Código.

La resolución que imponga una medida cautelar, así como la que la rechace o sustituya por otra, podrá revocarse o reformarse de oficio o a petición de parte, cualquiera que sea el estado en que el proceso se encuentre.','174','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":180,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"9a9715066d6794bd9bf02ddcbef57f729c2b16abc3cbad56ee52221b85eb1caf","article_sha256":"868b76629744f4d842a1adb2d56e1eb9ac7d5f943930e26031e52756b1e4f5b0","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a174","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','174','868b76629744f4d842a1adb2d56e1eb9ac7d5f943930e26031e52756b1e4f5b0','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:175','mayalex_normativos','01_PENAL','Aprehensión de las personas. La Policía Nacional podrá aprehender a cualquier persona aún sin orden judicial en los casos siguientes:

1) En caso de flagrante delito, entendiéndose que se produce tal situación cuando:

a) Sea sorprendida cometiendo el delito o en el momento de ir a cometerlo; y,

b) Sea sorprendida inmediatamente después de cometido el delito.

2) Cuando la persona sorprendida en alguno de los dos casos anteriores, está siendo perseguida por la fuerza pública, por el ofendido o por otras personas.

En ambos casos, cualquier persona podrá también proceder a la aprehensión y adoptar las medidas necesarias para evitar que el delito produzca consecuencias.

La persona aprehendida será entregada inmediatamente a la autoridad más próxima;

3) Cuando existan indicios muy fundados de haberse cometido un delito y la persona aprehendida haya sido sorprendida teniendo en su poder armas, instrumentos o efectos procedentes del delito o falta, o presente señales o vestigios que permitan inferir la participación del aprehendido en la infracción cometida o intentada;

4) Cuando existan indicios muy fundados de haberse cometido un delito, de haber participado en él la persona aprehendida y que ésta pueda tratar de ocultarse, fugarse o ausentarse del lugar; y,

5) Cuando al iniciarse las investigaciones, en la imposibilidad de distinguir entre las personas presentes en el lugar, a los partícipes en el hecho y a los testigos, exista necesidad urgente de impedir que alguna de ellas se ausente, o se comuniquen entre sí, así como evitar que puedan modificar en cualquier forma, el estado de las cosas o el lugar del delito.

En este último caso, una vez acreditada la ausencia de indicios de participación respecto de una o más de las personas retenidas, serán estas dejadas en libertad, una vez recibida la información necesaria para la investigación y dejada constancia de los datos relativos a su identidad.

La Policía Nacional podrá también aprehender nuevamente a la persona que consiga fugarse después de una primera aprehensión, lo mismo a la que se hubiera evadido del establecimiento donde se encontrará en calidad de detenido, preso o penado, o durante su traslado desde o hacia dicho establecimiento.

Dentro de las seis (6) horas siguientes al momento de la aprehensión, la autoridad policial que la haya practicado o a la que le haya sido entregada la persona sorprendida in fraganti, dará cuenta del hecho al Ministerio Público y al juez competente. Si la captura la realiza la Policía Preventiva, deberá poner a la persona aprehendida, de manera

inmediata, a la orden de la Dirección Nacional de Investigación Criminal (DNIC)20, así como los instrumentos, los efectos del delito y las piezas de convicción si las hubiere.','175','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":181,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"49a76b2f43402a6aaef73b4f470385844a9cc81a27745def3cbf656580e5f6f5","article_sha256":"f85e033d606c9d85b17b1225a47ce66691a7dcd1ab6bc7c69ffcb83ecc878d7f","constancias":[{"nota":20,"tipo":"CAMBIO_INSTITUCIONAL","texto":"Se suprime la Dirección Nacional de Investigación Criminal (DNIC) y crea la Dirección Policial de Investigaciones (DPI) mediante Decreto Ejecutivo Número PCM-063-2015 de fecha 14 de septiembre de 2015 y publicado en el Diario Oficial la Gaceta No. 33,979 de fecha 8 de marzo de 2016.","decretos":["PCM-063-2015"]},{"nota":45,"tipo":"CAMBIO_INSTITUCIONAL","texto":"Se suprime la Dirección Nacional de Investigación Criminal (DNIC) y crea la Dirección Policial de Investigaciones (DPI) mediante Decreto Ejecutivo Número PCM-063-2015 de fecha 14 de septiembre de 2015 y publicado en el Diario Oficial la Gaceta No. 33,979 de fecha 8 de marzo de 2016","decretos":["PCM-063-2015"]}],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a175","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','175','f85e033d606c9d85b17b1225a47ce66691a7dcd1ab6bc7c69ffcb83ecc878d7f','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:176','mayalex_normativos','01_PENAL','Detención preventiva. El Ministerio Público podrá ordenar la detención preventiva de una persona cuando:

1) Existan razones para creer que participó en la comisión de un delito y que puede ocultarse, fugarse o ausentarse del lugar;

2) Al iniciarse las investigaciones, no puedan identificarse los presuntos imputados o testigos y haya que proceder con urgencia, a fin de evitar que quienes estuvieron presentes en el lugar en que se cometió el delito se alejen del mismo, se comuniquen entre sí o se modifique en cualquier forma, el estado de las cosas o el lugar del delito; y,

3) Sin justa causa, cualquier persona obligada a prestar declaración, se niegue a hacerlo después de haber sido debidamente citada.

Toda detención preventiva será puesta sin tardanza en conocimiento del juez competente y en ningún caso podrá exceder de veinticuatro (24) horas o cuarenta y ocho (48) en aquellos casos en que investiguen los delitos de investigación complejas, acusa de la multiplicidad de los hechos relacionados, dificultades en la obtención de pruebas o por elevado número de imputados o víctimas.

La orden de detención preventiva deberá contener la denominación de la autoridad de quien emane; el lugar y la fecha de su expedición; el nombre, apellidos y demás datos que sirvan para identificar a quien debe detenerse, la causa de la detención y la firma y sello de quien la expide.

Salvo en los casos previstos en los artículos 279, 281 y 282, la Policía Nacional no podrá ordenar o practicar la detención preventiva de persona alguna.','176','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":182,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"7226c1508e52c1907489ed344f91422fa1cca4b478a6733c650f224c2b9fd4c9","article_sha256":"5df38d1f3de73bb75b1c8a6dc526ce235dec76c4dbedfb017c582d2ceec252b1","constancias":[{"nota":21,"tipo":"REFORMA","texto":"Artículo 176. Reformado por Decreto 74-2013 de fecha 8 de mayo de 2013 y publicado en el Diario Oficial La Gaceta No.33,301 de fecha 11 de diciembre de 2013.","decretos":["74-2013"]}],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a176","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','176','5df38d1f3de73bb75b1c8a6dc526ce235dec76c4dbedfb017c582d2ceec252b1','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:177','mayalex_normativos','01_PENAL','El allanamiento. Si la persona que deba ser aprehendida o detenida preventivamente se encuentra en una casa de habitación propia o ajena, el allanamiento para su captura solo podrá verificarse con el consentimiento de quien habite en aquélla o mediante autorización judicial. Con todo, la casa en referencia podrá ser allanada, en los casos y con las condiciones establecidas por el artículo 212 de este Código.

Las autorizaciones a que se refiere el párrafo anterior, no serán necesarias para entrar en establecimientos públicos, negocios, comercios, centros de reunión o recreo y, en general, en cualquier lugar urbano o rural, que no sirva de casa de habitación, residencia o domicilio de una persona.','177','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":183,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"d82b8fecc4f8cd7a7ffd422aa59f16de1386f2ae6019fcf6f7d99ccd94c0415d","article_sha256":"1a4ab2db76f8dd8771696194fed331d31e071a66aa254e08dfa28fd51c359b25","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a177","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','177','1a4ab2db76f8dd8771696194fed331d31e071a66aa254e08dfa28fd51c359b25','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:178','mayalex_normativos','01_PENAL','De la prisión preventiva. Por prisión preventiva se entenderá la privación de libertad que se produzca, durante el proceso, en cumplimiento de la orden emitida

por el órgano jurisdiccional competente, hasta que la sentencia definitiva adquiera el carácter de firme.

Para ordenar la prisión preventiva, deberá concurrir alguna de las circunstancias siguientes:

1) Peligro de fuga del imputado;

2) La posible obstrucción de la investigación por parte del imputado;

3) Riesgo fundado de que el imputado se reintegre a la organización delictiva a la que hay sospecha que pertenece y, utilice los medios que ella le brinde para entorpecer la investigación o facilitar la fuga de otros imputados; y,

4) Riesgo fundado de que el imputado atente o ejecute actos de represalia en contra del acusador o denunciante.

En la resolución que ordene la prisión preventiva, se deberá consignar expresamente la causa o causas en que se funde, así como los indicios resultantes de las actuaciones practicadas, que se hayan tenido en cuenta para acordarla.','178','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":184,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"45b2f1f8311fd337a86a2d4cf2b7765a53e69c172e900478ebc2e271f90c23c5","article_sha256":"2ccd0738efc3ed78870a3e6372019ef9abe681c63fbf845a4d2fe82d4116d696","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a178","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','178','2ccd0738efc3ed78870a3e6372019ef9abe681c63fbf845a4d2fe82d4116d696','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:179','mayalex_normativos','01_PENAL','Peligro de fuga del imputado. Para determinar si existe peligro de fuga del imputado, se tendrán en cuenta las circunstancias siguientes:

1) La falta de arraigo en el país, teniendo en cuenta el domicilio del imputado, el asiento de su familia, de sus negocios o de su trabajo, y las facilidades con que cuente para abandonar definitivamente el territorio nacional o para permanecer oculto;

2) La gravedad de la pena que pueda imponerse al imputado, como resultado del proceso;

3) La importancia del daño que deba indemnizar y la actitud del imputado frente al mismo y, en particular, su falta de voluntad reparadora; y,

4) El comportamiento del imputado durante el proceso, en cualquier otro anterior o en las diligencias previas, del que razonablemente pueda inferirse su falta de voluntad para someterse a la investigación o al proceso penal.','179','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":185,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"cb5ddfd4e908bf08432ef9fb72111d7a7675b065304977da8b8215a4309cecb5","article_sha256":"4fc4e2ef69dd9ca40b01cbb5d4d922fe3273a4866eea35a39f45a238fc0c553f","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a179","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','179','4fc4e2ef69dd9ca40b01cbb5d4d922fe3273a4866eea35a39f45a238fc0c553f','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:180','mayalex_normativos','01_PENAL','Peligro de obstrucción. Para decidir acerca del peligro de obstrucción de la investigación, se tendrá en cuenta todo indicio racional del cual se infiera que el imputado:

1) Destruirá, modificará, ocultará, suprimirá o falsificará la prueba o pruebas existentes, relacionadas con el delito;

2) Influirá en los demás imputados o en los testigos o peritos, para que informen falsamente sobre lo que saben o para que se comporten de manera desleal o reticente; y,

3) Forzará o inducirá a otros interesados a observar los comportamientos previstos en el numeral anterior.

4) Riesgo fundado de que el imputado se reintegre a la organización delictiva de la que hay sospecha pertenece y utilice los medios que ella le brinde a fin de infringir un temor racional en los intervinientes del proceso.

Los motivos precedentes solo servirán de fundamento para la prisión preventiva del imputado, hasta la conclusión del debate.','180','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":186,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"3fab5d3019667b4f55f2de1a678fa0c8ea3b65947a81e4fdb5c998f03d589fcb","article_sha256":"84508cd4ea3306429dc7a52c7a32ab19b10450eb0986973035f5e0204d2566b4","constancias":[{"nota":22,"tipo":"REFORMA","texto":"Artículo 180. Reformado por Decreto 74-2013 de fecha 8 de mayo de 2013 y publicado en el Diario Oficial La Gaceta No.33, 301 de fecha 11 de diciembre de 2013.","decretos":["74-2013"]}],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a180","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','180','84508cd4ea3306429dc7a52c7a32ab19b10450eb0986973035f5e0204d2566b4','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:181','mayalex_normativos','01_PENAL','Duración de la prisión preventiva. La prisión preventiva podrá durar, como regla general, hasta un (1) año.

Cuando la pena aplicable al delito sea superior a seis (6) años, la prisión preventiva podrá durar hasta dos (2) años.

Excepcionalmente, y habida cuenta del grado de dificultad, dispersión o amplitud de la prueba que deba rendirse, la Corte Suprema de Justicia podrá ampliar hasta por seis (6) meses los plazos a que este artículo se refiere, a solicitud fundada del Ministerio Público.

En ningún caso, la prisión preventiva podrá exceder de la mitad de la duración del mínimo de la pena aplicable al delito.

Una vez dictada la sentencia condenatoria, la prisión preventiva podrá prolongarse durante la tramitación y resolución del recurso que contra ella pueda interponerse, hasta la mitad de la pena impuesta en la sentencia recurrida. Si el máximo así determinado excediere del ordinario establecido en este artículo, el tribunal, siempre que lo solicite alguna de las partes, oídas las demás, lo acordará por auto motivado.

Dentro de dicho plazo, no se contará el tiempo que hayan durado las demoras producidas por gestiones de la defensa, que hayan sido declaradas sin lugar.

Si vencido el plazo no ha llegado a su fin el proceso, el imputado será puesto en libertad provisional y sometido a cualquiera de las medidas cautelares previstas en el artículo 173, sin perjuicio de la continuación del proceso, hasta que la sentencia adquiera el carácter de firme.

Cuando dentro del plazo indicado no se dé fin al proceso, los funcionarios y empleados que hayan dado lugar al retraso por malicia, culpa o negligencia, serán sancionados de conformidad con la Ley de la Carrera Judicial, sin perjuicio de la responsabilidad penal en que hayan incurrido. La Corte Suprema de Justicia y el Ministerio Público, velarán por el estricto cumplimiento de lo dispuesto en este párrafo.','181','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":187,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"6d71c23d646a72a573a9b93fa9114fc27f505e552bf75eb88e659b9dacf429aa","article_sha256":"890c5fdc2078c8ec0062875179f769d92e54a5fc5f31e71111f349f15ef051ab","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a181","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','181','890c5fdc2078c8ec0062875179f769d92e54a5fc5f31e71111f349f15ef051ab','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:182','mayalex_normativos','01_PENAL','Prohibición de la prisión preventiva. Salvo el caso previsto en el artículo 178 numeral 4) y el artículo 179 de este Código, en los delitos en los que la pena aplicable no sea privativa de libertad o en aquellos en que el máximo de la pena sea inferior a cinco (5) años de reclusión, no se impondrá la prisión preventiva, sino solo las medidas sustitutivas, las que serán decretadas, teniendo en cuenta las circunstancias y la naturaleza de cada caso.','182','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":188,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"4465642be12bfae31dde3a223413c08797cfb668fcfe872ba2ef859ddf18cc31","article_sha256":"24ff21690809cf881fc84a4413238e920dcf28f65dbf0786c896b0e2ee6fe4c2","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a182","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','182','24ff21690809cf881fc84a4413238e920dcf28f65dbf0786c896b0e2ee6fe4c2','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:183','mayalex_normativos','01_PENAL','Casos en que no podrá decretarse prisión preventiva. No podrá decretarse prisión preventiva contra:

1) Los mayores de setenta (70) años;

2) Las mujeres en estado de embarazo;

3) Las madres durante la lactancia de sus hijos; y,

4) Las personas afectadas por una enfermedad en su fase terminal;

5) Quien actué al amparo del artículo 24 numeral 1 del Código Penal.

En tales casos, la prisión preventiva se sustituirá por arresto domiciliario o internamiento en un centro médico según las circunstancias; en los supuestos contenidos en los numerales 1,2 y 3 de este artículo esta medida cautelar será sustituida siempre y cuando, no exista los riesgos procesales descritos en el artículo 178 numerales 1,2,3 y 4 de este Código.','183','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":189,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"4cd6d3839dff28f55efa7133fe27dffbce150611c036b8926cf5874a61ce9af0","article_sha256":"f1a61ca6f6ec055d22f29534c8fd810952932c29b4008878edb4e2864a596b09","constancias":[{"nota":23,"tipo":"REFORMA","texto":"Artículo 183. Reformado por Decreto 74-2013 de fecha 8 de mayo de 2013 y publicado en el Diario Oficial La Gaceta No.33,301 de fecha 11 de diciembre de 2013.","decretos":["74-2013"]}],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a183","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','183','f1a61ca6f6ec055d22f29534c8fd810952932c29b4008878edb4e2864a596b09','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:184','mayalex_normativos','01_PENAL','Sustitución de la prisión preventiva. Siempre que los riesgos a que se refiere el artículo 178 puedan ser evitados por la aplicación de otra medida menos gravosa para su libertad, el Juez, de oficio o a petición de parte, puede imponer al imputado, en lugar de la prisión preventiva, una o más de las medidas comprendidas en los numerales 4), 5), 6), 7), 8), 9) y 10) del artículo 173.

Las medidas anteriores pueden ser impuestas en forma simultánea o sucesiva.

El juez velará por el estricto cumplimiento de la medida impuesta, para lo cual debe contar con el apoyo de la Policía Nacional y cualquier otra institución de seguridad del Estado.

Las medidas alternativas de la prisión preventiva no pueden imponerse si existe grave riesgo de que no se logre la finalidad perseguida.

En los casos en que el imputado no tenga capacidad para rendir una caución de naturaleza económica, puede decretarse caución juratoria, la cual consistirá en prestar juramento de someterse al procedimiento. La caución juratoria debe decretarse conjuntamente con la medida a que se refiere al numeral 6) del artículo 173 y cualquiera otra que el Juez considere conveniente.

En ningún caso procederá la aplicación de otra medida cautelar distinta a la prisión preventiva, en los delitos de narcotráfico, violación especial, tráfico de armas o delitos relacionados con grupos criminales conocidos como “maras o pandillas”.','184','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":190,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"8a5fb3f68db38c22804611f1d9d514b4a78f62e7f6c1ad22d707755e9b0b4374","article_sha256":"1d9e50790ef7c456c5e793ab05378ca144316d5567cadff284eaf2b680dff032","constancias":[{"nota":24,"tipo":"REFORMA","texto":"Artículo 184. Reformado. Por Decreto 36-2020 de fecha 24 de abril de 2020 y publicado en el Diario Oficial La Gaceta No.35,279 de fecha 10 de junio de 2020.","decretos":["36-2020"]}],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a184","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','184','1d9e50790ef7c456c5e793ab05378ca144316d5567cadff284eaf2b680dff032','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:185','mayalex_normativos','01_PENAL','Internamiento cautelar. Si dándose los presupuestos justificados de la prisión preventiva, se comprueba por dictamen pericial, que la persona que ha de ser sometida a ella se haya en un estado de enfermedad mental, cuyo tratamiento sea incompatible con el cumplimiento de la medida cautelar en un establecimiento penal, el órgano jurisdiccional, podrá ordenar que se lleve a cabo en un establecimiento especializado, adoptando las precauciones necesarias para impedir la fuga de la persona internada.

Este internamiento no podrá durar más que la prisión preventiva ordinaria y concluirá cuando haya cesado la situación descrita en el párrafo anterior, en cuyo caso, el órgano jurisdiccional dispondrá si procede mantenerla privada cautelarmente de su libertad en establecimiento penal, o adoptar una medida sustitutiva.','185','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":191,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"d0ff23b5642889e2fa293843fd30329f410a5c82817aa776e7b7919090f6c03e","article_sha256":"dbea6730f9016e9e003a6ee6537e56e576ee72b7c7173fb912998b9a6fd06f55","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a185","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','185','dbea6730f9016e9e003a6ee6537e56e576ee72b7c7173fb912998b9a6fd06f55','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:186','mayalex_normativos','01_PENAL','Forma y contenido de las resoluciones que decreten prisión preventiva o medidas sustitutivas. Las resoluciones que decreten la prisión preventiva, el internamiento o las medidas sustitutivas, deberán contener:

1) La denominación del juzgado que adopte la medida, lugar de emisión y fecha de aquella;

2) Los datos personales del imputado o los que sirvan para identificarlo;

3) Una sucinta relación del hecho o hechos que se atribuyan al imputado, con su calificación legal;

4) Los fundamentos de la imposición de la medida, con indicación de los presupuestos que la motiven, especificando, en su caso, la existencia de peligro de fuga, de obstrucción de las investigaciones, de que existen motivos suficientes para presumir que el imputado continuará su actividad delictiva o que pueda atentar o ejercer actos de represalia contra el acusador o denunciante; expresando los indicios tenidos en cuenta, así como, las normas aplicables al caso;

5) La parte dispositiva, con clara expresión de la medida aplicable, su régimen de cumplimiento y duración máxima; y,

6) La firma y sello del juez que dicta la medida y del respectivo secretario.

Cada tres (3) meses el juez examinará si las medidas impuestas deben mantenerse o ser sustituidas por otras o revocadas.','186','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":192,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"aecf8b8fa18ef1aa115aa0eaceeca7df2bd74b5b1b17133b9a507582c3e6e2e4","article_sha256":"6fcd780640ca8947494dfcd391dbac11ccfd0c30541af2038ae1069d71197416","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a186","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','186','6fcd780640ca8947494dfcd391dbac11ccfd0c30541af2038ae1069d71197416','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:187','mayalex_normativos','01_PENAL','Contenido del acta que registre una medida sustitutiva. Antes de poner en práctica las medidas sustitutivas de la prisión preventiva a que se refiere el artículo 184, el secretario formulará un acta que deberá contener:

1) Denominación del juzgado de que se trate y lugar y fecha del acta;

2) Constancia de que se notificó al imputado la correspondiente resolución;

3) La dirección exacta de las personas que habrán de intervenir en la ejecución de las medidas impuestas y la aceptación por parte de dichas personas, de la función u obligación que se les haya asignado;

4) La indicación precisa de las consecuencias que para el imputado tendrá el incumplimiento de las medidas impuestas;

5) La dirección exacta en que puedan hacérsele notificaciones, citaciones y emplazamientos al imputado;

6) La promesa formal del imputado de cumplir las medidas que se le hayan impuesto y de permanecer a la disposición del órgano jurisdiccional; y,

7) La firma del secretario y demás intervinientes.','187','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":193,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"f046421fb4221ecb0df2a6dd48342df9df3146deeaa8f0bbdea75ef4dccc0c47","article_sha256":"194e47f718f6306b3fb4366542cd005dc39436a9c9b20b027098d6d93b25c11c","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a187","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','187','194e47f718f6306b3fb4366542cd005dc39436a9c9b20b027098d6d93b25c11c','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:188','mayalex_normativos','01_PENAL','Revocación o sustitución de medidas cautelares privativas de libertad. El juez, de oficio o a petición de parte, revocará o sustituirá la resolución en que se ordene la prisión preventiva del imputado, por otras medidas cautelares, cuando:

1) Hayan desaparecido los presupuestos que se tuvieron en cuenta para dictarla;

2) El indiciado haya estado recluido por un tiempo igual o superior a la de la duración mínima de la pena prevista para el delito de que se trate;

3) Haya transcurrido el plazo máximo de duración de la prisión preventiva, y su prórroga, en caso de que ésta haya sido excepcionalmente acordada; y,

4) La restricción de la libertad del imputado haya adquirido las características de una pena anticipada o provocado limitaciones a su libertad, que excedan las imprescindibles para evitar los riesgos a que se refiere el artículo 178 de este Código.','188','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":194,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"e4868cd4f96eb7dc10eb2c6d0561092988cd22bfa3576493e286d46d7335b8c7","article_sha256":"c238373bf273f17a79be092bb68879c663bd6305a689bafecd477108df092272","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a188","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','188','c238373bf273f17a79be092bb68879c663bd6305a689bafecd477108df092272','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:189','mayalex_normativos','01_PENAL','Trámite de la revocación o sustitución de la resolución que ordene la prisión preventiva. La revocación o sustitución a que se refiere el artículo anterior, se adoptará en audiencia oral celebrada para el efecto.

Dicha audiencia tendrá lugar dentro de las cuarenta y ocho (48) horas siguientes a la fecha de la decisión del juez de revisar la medida, o de la fecha en que se haya presentado la respectiva petición. Se celebrará con citación del fiscal y de las partes, aunque se llevará a cabo con quienes concurran. Finalizada la audiencia, el juez resolverá por auto motivado, lo que estime procedente, en el mismo día o en el inmediato siguiente.','189','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":195,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"bf1e2b135b701ba827c63566979bd8dc478a3d92847b3201f5461d4873c5b18d","article_sha256":"fde90d20cf71c4785acf49660102523e94bc4282df64dca4c4d4674624e246db","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a189","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','189','fde90d20cf71c4785acf49660102523e94bc4282df64dca4c4d4674624e246db','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:190','mayalex_normativos','01_PENAL','Apelación de las resoluciones relacionadas con la prisión preventiva. Las resoluciones que impongan, modifiquen o declaren sin lugar una medida cautelar, serán apelables en un solo efecto.

El recurso de apelación no suspenderá el cumplimiento de la medida apelada. En tal caso, el emplazamiento no podrá exceder de veinticuatro (24) horas, más el término de la distancia.

Admitido el recurso, el juez remitirá sin tardanza, al tribunal de apelación, copia de las actuaciones que guardan relación con la resolución apelada a criterio del titular del órgano jurisdiccional, quien certificará la misma. La Corte de Apelaciones resolverá sin más trámite dentro de los tres (3) días siguientes de recibidas las actuaciones.','190','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":196,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"c52e1df8e0033be2c9dc1cd606c702ec5a677eaa2e4824512cab53adca04b504","article_sha256":"74758265e574001ca0dd8fa9a33295d3a785db05b83d8af6fc18a75804ee3198","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a190","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','190','74758265e574001ca0dd8fa9a33295d3a785db05b83d8af6fc18a75804ee3198','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:191','mayalex_normativos','01_PENAL','Lugar de cumplimiento de la prisión preventiva y tratamiento del imputado. Las personas contra quienes se haya dictado prisión preventiva, cumplirán ésta en las cárceles y presidios del país, pero en lugares absolutamente separados de los que ocupan quienes hayan sido condenadas.

El imputado, en todo momento, será tratado como inocente y teniendo en cuenta que se encuentra detenido para el solo efecto de asegurar su comparecencia en el proceso o, en su caso, el cumplimiento de la pena.

La prisión preventiva se cumplirá de tal manera, que no adquiera las características de una pena, ni provoque al imputado otras limitaciones que las imprescindibles para evitar su fuga, la obstrucción de la investigación o que continúe en la actividad delictiva.

El Juez de Ejecución velará por el estricto cumplimiento de esta norma. Cuando constate que la prisión preventiva ha adquirido las características de una pena, comunicará el hecho, sin tardanza, al órgano jurisdiccional que conoce del proceso, quien resolverá lo procedente dentro de las veinticuatro (24) horas siguientes.','191','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":197,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"c7a43fd12b612ef78f00bc862a03387aa8fd4f3fe8977351f3aadfd7e769ecb5","article_sha256":"7834417a3a1ef312db9afb4df14a1d4ab03cf6cc069c11c3585ebac364a59158","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a191","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','191','7834417a3a1ef312db9afb4df14a1d4ab03cf6cc069c11c3585ebac364a59158','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:192','mayalex_normativos','01_PENAL','Incomunicación del imputado sujeto a prisión preventiva. El juez, a petición del fiscal a cuyo cargo se encuentre la investigación, podrá disponer la incomunicación del imputado por un plazo no mayor de veinticuatro (24) horas, si existen motivos fundados para temer que, de otra manera, obstruirá un acto concreto de la investigación. El juez, en su decisión, hará constar los motivos en que funda.

La incomunicación no impedirá que el imputado se comunique con su defensor inmediatamente antes de rendir su declaración o antes de realizar cualquier acto que requiera su intervención personal, ni tampoco el acceso a libros, revistas, periódicos u otros objetos análogos.

En casos de urgencia excepcional, en que la demora para solicitar del juez la incomunicación, pueda frustrar o perjudicar gravemente la investigación en curso, el Ministerio Público podrá acordarla; pero esta incomunicación no podrá exceder de seis (6) horas, dentro de las cuales deberá gestionar la correspondiente orden judicial. El juez, oídas las razones expuestas por el Ministerio Público, confirmará su decisión o la dejará sin efecto, convalidando o anulando, total o parcialmente, lo realizado durante la incomunicación.','192','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":198,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"9afd9f0a86ccc95a9c92f781e2b538e2beb5e53fe3dfedc5b30a2cceec5388c7","article_sha256":"22996773132ad428d098cb86c8039bfc11ad1ba357f6e539056071798cbc52f0","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a192","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','192','22996773132ad428d098cb86c8039bfc11ad1ba357f6e539056071798cbc52f0','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:193','mayalex_normativos','01_PENAL','Las cauciones. La caución podrá ser fianza, o garantía real.

La fianza podrá otorgarla todo aquel que tenga capacidad para contratar y disponer y que sea propietario de bienes suficientes para responder por la cuantía de la caución establecida por el juez. Tales bienes podrán ser muebles, inmuebles o depósitos bancarios y, su existencia se probará con los atestados o certificaciones correspondientes.

La caución real se constituirá mediante hipoteca, prenda o depósito de dinero.

Si la caución es prestada por persona distinta del imputado, aquélla no gozará del beneficio de la excusión.

Con autorización del juez, podrá sustituirse la caución rendida por otra equivalente.','193','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":199,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"153901d7698ef7df719fff5a7db5fc60c8a07a3a0300a74425606a3ed19ba7da","article_sha256":"032d07635b54ffcd389df1c7d4f14461edc3ba3cebcaecad30866b0d617a9647","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a193","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','193','032d07635b54ffcd389df1c7d4f14461edc3ba3cebcaecad30866b0d617a9647','OLA1_CPP_2024_01',now()),
('OLA1_CPP_2024_01:CODIGO_PROCESAL_PENAL:194','mayalex_normativos','01_PENAL','Cuantía y naturaleza de las cauciones. La cuantía y naturaleza de las cauciones condicionales de la libertad provisional cuando proceda con arreglo a este Código, serán fijadas por el juez, tomando en consideración la gravedad del delito, la capacidad económica del imputado, su personalidad moral y sus antecedentes.','194','Código Procesal Penal de Honduras (Decreto 9-99-E)','{"norm_id":"HN:CODIGO_PROCESAL_PENAL","instrumento_id":"CODIGO_PROCESAL_PENAL","ingest_batch":"OLA1_CPP_2024_01","ola":"OLA1","ordinal":200,"decreto":"9-99-E","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Compilación consolidada del Centro Electrónico de Documentación e Información Judicial (CEDIJ), Poder Judicial de Honduras -- edición con reformas integradas de los Decretos 14-2006 (Arts. 26-A, 219-A), 22-2015 (Arts. 237-A, 237-B), 70-2015 (Arts. 402-A al 402-G), 74-2013 (Arts. 440-A al 440-O, Flagrancia) y 195-2004 (Arts. 414-417)","pdf_sha256":"71eb53b174b4fdd1af4e08ba084015caf5cd14c459b4277f34533a83bff391a4","fragmento_fuente_sha256":"a094a15874bba5357996287d9ea5c25b14ab9d5f4522f5077d0cb2392c614ef6","article_sha256":"046397fdf6c4b86bcdefdcab0bd2c8614044ed8334c9e1dc1890a3935b574620","constancias":[],"correcciones_saneamiento":["REFLUJO_DE_LINEAS"],"sustituye_id_legacy":"mayalex_normativos:cpp_1999_a194","clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ (Poder Judicial) con reformas integradas; cotejo con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'CODIGO_PROCESAL_PENAL','194','046397fdf6c4b86bcdefdcab0bd2c8614044ed8334c9e1dc1890a3935b574620','OLA1_CPP_2024_01',now())
