DO $do$ DECLARE n int; BEGIN
  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA1_CPP_2024_01' AND metadata->>'norm_id' = 'HN:CODIGO_PROCESAL_PENAL'
    AND instrumento_id = 'CODIGO_PROCESAL_PENAL' AND jurisdiccion = 'HN' AND encode(sha256(convert_to(contenido, 'UTF8')), 'hex') = hash_contenido AND revision_pendiente = true AND es_norma_vigente IS NULL;
  IF n <> 480 THEN RAISE EXCEPTION 'post-insert prod (ocultas, hash correcto): % filas (esperadas 480)', n; END IF;
END $do$;
COMMIT;
